const TAG_TO_TEMPLATE = {
  14: 97, 15: 98, 8: 99, 13: 100,
};
const TAG_TO_AREA = {
  14: 'imigracao', 15: 'imigracao', 7: 'imigracao',
  8: 'empresas', 9: 'familia', 10: 'impostos',
  11: 'imobiliario', 12: 'documentos', 13: 'diversos',
};
const TAG_TO_SERVICE = {
  14: 'Nacionalidade Portuguesa', 15: 'Visto Português',
  7: 'Imigração (Geral)', 8: 'Abertura de Empresa',
  9: 'Família', 10: 'Impostos', 11: 'Imobiliário',
  12: 'Documentos', 13: 'Consulta Técnica',
};

const body = $input.first().json.body || $input.first().json;
const tagIds = body.tag_ids || [];

let templateId = null;
let lawArea = 'diversos';
let serviceType = '';

for (const tagId of tagIds) {
  if (TAG_TO_TEMPLATE[tagId]) templateId = TAG_TO_TEMPLATE[tagId];
  if (TAG_TO_AREA[tagId]) lawArea = TAG_TO_AREA[tagId];
  if (TAG_TO_SERVICE[tagId]) serviceType = TAG_TO_SERVICE[tagId];
}

let cleanName = (body.name || 'Sem nome')
  .replace(/^\[Lead\]\s*/i, '')
  .replace(/\s*-\s*Fale Conosco CF$/i, '')
  .replace(/\s*-\s*Reunião Mentoria Advogar em Portugal$/i, '')
  .replace(/\s*-\s*Lead Manual$/i, '')
  .replace(/^Consulta Calendly\s*[—–-]\s*/i, '')
  .replace(/^Fale Conosco CF\s*-\s*/i, '')
  .trim();

if (serviceType) {
  cleanName = cleanName + ' — ' + serviceType;
}

const contactName = body.contact_name || cleanName.split(' — ')[0];
const email = body.email_from || '';
const phone = body.phone || '';

return [{
  json: {
    lead_name: cleanName,
    contact_name: contactName,
    email: email,
    phone: phone,
    expected_revenue: body.expected_revenue || 0,
    tag_ids: tagIds,
    template_id: templateId,
    law_area: lawArea,
    service_type: serviceType,
  }
}];

const data = $input.first().json;
const templateId = $('Routing por Tag').first().json.template_id;

return [{
  json: {
    project_id: data.project_id,
    template_id: templateId,
    has_template: templateId !== null
  }
}];

const response = $input.first().json;
const tasks = response.result || [];
const projectId = $('Extrair Project ID').first().json.project_id;

if (tasks.length === 0) {
  return [{ json: { project_id: projectId, tasks_count: 0, message: 'Template sem tarefas' } }];
}

// Preparar batch de tarefas para criar
const taskPayloads = tasks.map(task => ({
  project_id: projectId,
  name: task.name,
  sequence: task.sequence,
  description: task.description || '',
  priority: task.priority || '0',
  user_ids: task.user_ids && task.user_ids.length > 0 ? [[6, 0, task.user_ids]] : [[6, 0, [6]]]
}));

return taskPayloads.map(t => ({ json: t }));

// Sem template — projecto criado sem tarefas
const projectId = $('Extrair Project ID').first().json.project_id;
const routing = $('Routing por Tag').first().json;

return [{
  json: {
    status: 'ok',
    project_id: projectId,
    message: 'Projeto criado SEM tarefas (sem template para tag)',
    service_type: routing.service_type,
    law_area: routing.law_area
  }
}];

const data = $input.first().json;

const projectData = {
  name: data.lead_name,
  stage_id: 25,
  type_ids: [[6, 0, [9, 10, 11]]],
  allow_timesheets: true,
  allow_billable: true,
  description: 'Criado automaticamente via n8n a partir do lead CRM'
};

if (data.partner_id) {
  projectData.partner_id = data.partner_id;
}

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://odoo.telejud.com/jsonrpc',
  headers: { 'Content-Type': 'application/json' },
  body: {
    jsonrpc: '2.0',
    method: 'call',
    params: {
      service: 'object',
      method: 'execute_kw',
      args: [
        'odoo18', 2,
        '0fd980f86424e522826d5a2da33e63a5d8a095c1',
        'project.project', 'create',
        [projectData],
        {}
      ]
    }
  }
});

return [{ json: { project_id: response.result, lead_name: data.lead_name } }];

const items = $input.all();
const results = [];

for (const item of items) {
  const task = item.json;

  const userIds = Array.isArray(task.user_ids) && typeof task.user_ids[0] === 'number' 
    ? [[6, 0, task.user_ids]] 
    : [[6, 0, [6]]];

  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://odoo.telejud.com/jsonrpc',
      headers: { 'Content-Type': 'application/json' },
      body: {
        jsonrpc: '2.0',
        method: 'call',
        params: {
          service: 'object',
          method: 'execute_kw',
          args: [
            'odoo18', 2,
            '0fd980f86424e522826d5a2da33e63a5d8a095c1',
            'project.task', 'create',
            [{
              project_id: task.project_id,
              name: task.name,
              sequence: task.sequence,
              description: task.description || '',
              priority: task.priority || '0',
              user_ids: userIds
            }],
            {}
          ]
        }
      }
    });

    const taskId = response.result;
    const hasError = response.error;

    results.push({ 
      json: { 
        task_name: task.name, 
        task_id: taskId || null, 
        success: !hasError,
        error: hasError ? response.error.message : null
      } 
    });
  } catch (e) {
    results.push({ 
      json: { 
        task_name: task.name, 
        task_id: null, 
        success: false, 
        error: e.message 
      } 
    });
  }
}

return results;

const data = $input.first().json;
const email = data.email;
const name = data.contact_name;
const phone = data.phone;

let partnerId = null;

if (email) {
  const searchResult = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://odoo.telejud.com/jsonrpc',
    headers: { 'Content-Type': 'application/json' },
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          'odoo18', 2,
          '0fd980f86424e522826d5a2da33e63a5d8a095c1',
          'res.partner', 'search',
          [[['email', '=', email]]],
          {}
        ]
      }
    }
  });

  const existing = searchResult.result || [];

  if (existing.length > 0) {
    partnerId = existing[0];
  } else {
    const createResult = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://odoo.telejud.com/jsonrpc',
      headers: { 'Content-Type': 'application/json' },
      body: {
        jsonrpc: '2.0',
        method: 'call',
        params: {
          service: 'object',
          method: 'execute_kw',
          args: [
            'odoo18', 2,
            '0fd980f86424e522826d5a2da33e63a5d8a095c1',
            'res.partner', 'create',
            [{ name: name, email: email, phone: phone, is_company: false }],
            {}
          ]
        }
      }
    });
    partnerId = createResult.result;
  }
}

return [{
  json: {
    ...data,
    partner_id: partnerId
  }
}];
